local mArguments --initialize lazily
local mHatnote = require('Module:Hatnote')
local mHatList = require('Module:Hatnote list')
local libraryUtil = require('libraryUtil')
local checkType = libraryUtil.checkType
local p = {}

function p.For (frame)
	-- A passthrough that gets args from the frame and all
	mArguments = require('Module:Arguments')
	args = mArguments.getArgs(frame)
	return p._For(args)
end


function p._For (args, options)
	--Allow passing through certain options
	local fsOptions = {
		otherText = args.otherText,
		extratext = args.text
	}
	local hnOptions = {
		selfref = args.selfref
	}

	-- Set for-see list
	local forSee = mHatList._forSee(args, 1, fsOptions)

	local image = '[[File:Disambig_gray.svg|25px|link=Wikipedia:消歧义]]'

	-- Concatenate and return
	return mHatnote._hatnote(image .. '&nbsp;&nbsp;' .. forSee, hnOptions)
end
function p.MakeTemplate (frame)
	-- A passthrough that gets args from the frame and all
	mArguments = require('Module:Arguments')
	args = mArguments.getArgs(frame)
	return p._ForSeeList(args)
end


function p._ForSeeList (args, options)	
	--Allow passing through certain options
	local fsOptions = {
		otherText = args.otherText,
		extratext = args.text
	}
	local hnOptions = {
		selfref = args.selfref
	}

	-- Set for-see list
	local forSee = mHatList._forSee(args, 2, fsOptions)

	-- Concatenate and return
	local ret=mHatnote._hatnote(forSee, hnOptions)
	return string.sub(ret,41,string.len(ret)-5)--移除开头的<div>和结尾的</div>
end
return p

