{{distinguish|工作台}}
'''合成器（Crafter）'''是在接收到[[红石脉冲]]时能自动{{mcw|合成}}并向前丢出产物的[[方块]]。
== 获取 == === 合成 === 5个[[铁锭]]、2个[[红石粉]]、1个[[投掷器]]和1个[[工作台]]可以合成1个合成器。
== 破坏 == 合成器被破坏后会掉落自身。
== 用途 == {{main|w:c:zh.Minecraft:合成器#用途|title1=mcwzh:#用途}} === 红石比较器 === [[红石比较器]]可以检测合成器，并发出红石信号。信号强度等于被禁用与被物品占用的槽位数量之和，故可能的取值为0-9。
== 画廊 == {{main|w:c:zh.Minecraft:合成器#画廊|title1=mcwzh:#画廊}}
== 参见 == * [[工作台]] * {{mcw||中文Minecraft Wiki}}上的{{mcw}}

local mArguments=require('Module:Arguments')
local mHatlist = require('Module:Hatnote list')
local mHatnote = require('Module:Hatnote')
local yesNo = require('Module:Yesno')
local p = {}

--Implements {{distinguish}} from the frame
--uses capitalized "For" to avoid collision with Lua reserved word "for"
function p.Distinguish (frame)
	return p._distinguish(mArguments.getArgs(frame))
end
function p.distinguish (frame)
	return p._distinguish(mArguments.getArgs(frame))
end

--Implements {{distinguish}} but takes a manual arguments table
function p._distinguish (args)
	local use = args[1]
	local pages = {}
	table.insert(pages,use)
	function two (a, b) return a, b, 1 end --lets us run ipairs from 2
	for k, v in two(ipairs(args)) do table.insert(pages, v) end
	local image = '[[File:Disambig_gray.svg|25px|link=Wikipedia:消歧义]]'
	local dv='<div role="note" class="notice hatnote">'
	local frtxt=dv .. image .. '&nbsp;&nbsp;\'\'\'提示\'\'\'：本条目的主题不是'
	local ret=frtxt .. string.sub(mHatnote._hatnote(
		mHatlist.orlist(args,true,true,true),
		{selfref = args.selfref}
	) .. (
			(use == 'other uses') and yesNo(args.category) and
			'[[Category:使用不寻常参数的顶注模板]]' or ''
		),41)
	return ret
end

return p

