.navbox {
	border: 1px solid #aaa;
	box-sizing: border-box;
	width: 100%;
	margin: auto;
	clear: both;
	font-size: 88%;
	text-align: center;
	padding: 1px;
}

.navbox-inner,
.navbox-subgroup {
	width: 100%;
}

.navbox + .navbox-styles + .navbox {
	/* Single pixel border between adjacent navboxes */
	margin-top: -1px;
}

.navbox th,
.navbox-title,
.navbox-abovebelow {
	text-align: center;
	/* Title and above/below styles */
	padding-left: 1em;
	padding-right: 1em;
}

th.navbox-group {
	/* Group style */
	white-space: nowrap;
	/* @noflip */
	text-align: right;
}

.navbox,
.navbox-subgroup {
	background: #fdfdfd;
}
.navbox-list {
	/* Must match background color */
	border-color: #fdfdfd;
}

.navbox th,
.navbox-title {
	/* Level 1 color */
	background: #eaeeff;
}

.navbox-abovebelow,
th.navbox-group,
.navbox-subgroup .navbox-title {
	/* Level 2 color */
	background: #ddddff;
}

.navbox-subgroup .navbox-group,
.navbox-subgroup .navbox-abovebelow {
	/* Level 3 color */
	background: #e6e6ff;
}

.navbox-even {
	/* Even row striping */
	background: #f7f7f7;
}

.navbox-odd {
	/* Odd row striping */
	background: transparent;
}

th.navbox-title1 {
	border-left: 2px solid #fdfdfd;
	width: 100%;
}

td.navbox-list1 {
	text-align: left;
	border-left-width: 2px;
	border-left-style: solid;
}

.navbox .hlist td dl,
.navbox .hlist td ol,
.navbox .hlist td ul,
.navbox td.hlist dl,
.navbox td.hlist ol,
.navbox td.hlist ul {
	/* Adjust hlist padding in navboxes */
	padding: 0.125em 0;
}

.navbox .hlist dd,
.navbox .hlist dt,
.navbox .hlist li {
	/* Nowrap list items in navboxes */
	white-space: nowrap;
}

.navbox .hlist dd dl,
.navbox .hlist dt dl,
.navbox .hlist li ol,
.navbox .hlist li ul {
	/* But allow parent list items to be wrapped */
	white-space: normal;
}

ol + .navbox-styles + .navbox,
ul + .navbox-styles + .navbox {
	/* Prevent lists from clinging to navboxes */
	margin-top: 0.5em;
}

